  9	import java.math.BigDecimal;
 10	import java.net.URI;
 11	import java.net.http.HttpClient;
 12	import java.net.http.HttpRequest;
 13	import java.net.http.HttpResponse;
 14	import java.time.Duration;
 15	
 16	public class TransLogClient {
 17	    private final String transLogUrl;
 18	    private final HttpClient httpClient;
 19	    private final ObjectMapper objectMapper;
 20	
 21	    public TransLogClient(String transLogUrl) {
 22	        this.transLogUrl = transLogUrl;
 23	        this.httpClient = HttpClient.newBuilder()
 24	            .connectTimeout(Duration.ofSeconds(2))
 25	            .build();
 26	        this.objectMapper = new ObjectMapper();
 27	    }
 28	
 29	    public ShippingResult quote(String zipCode, BigDecimal weightKg, ShippingMethod method, Region region) {
 30	        String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
 31	        int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
 32	
 33	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
 34	            transLogUrl, zipCode, weightGrams, service);
 35	
 36	        try {
 37	            HttpRequest request = HttpRequest.newBuilder()
 38	                .uri(URI.create(url))
 39	                .timeout(Duration.ofSeconds(2))
 40	                .GET()
 41	                .build();
 42	
 43	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
 44	
 45	            if (response.statusCode() == 200) {
 46	                JsonNode json = objectMapper.readTree(response.body());
 47	
 48	                if (json.has("error")) {
 49	                    return null;
 50	                }
 51	
 52	                int priceCents = json.get("price_cents").asInt();
 53	                int etaHours = json.get("eta_hours").asInt();
 54	
 55	                BigDecimal price = MoneyUtils.roundMoney(new BigDecimal(priceCents).divide(new BigDecimal("100")));
 56	                int deliveryDays = (int) Math.ceil(etaHours / 24.0);
 57	
 58	                int additionalDays = switch (region) {
 59	                    case NORTH -> 3;
 60	                    case NORTHEAST -> 2;
 61	                    default -> 0;
 62	                };
 63	
 64	                return new ShippingResult(price, deliveryDays + additionalDays);
 65	            }
 66	        } catch (Exception e) {
 67	        }
 68	
 69	        throw new RuntimeException("CARRIER_UNAVAILABLE");
 70	    }
 71	}
 72	package com.loja.service.shipping;
 73	
 74	import com.loja.domain.*;
 75	import com.loja.util.ApiException;
 76	
 77	import java.math.BigDecimal;
 78	import java.util.List;
 79	import java.util.Map;
 80	
 81	public class ShippingCalculator {
 82	    private final TransLogClient transLogClient;
 83	
 84	    public ShippingCalculator(TransLogClient transLogClient) {
 85	        this.transLogClient = transLogClient;
 86	    }
 87	
 88	    public ShippingResult calculate(CheckoutRequest request, Map<String, Product> productMap) {
 89	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), productMap);
 90	
 91	        return switch (request.getShippingMethod()) {
 92	            case STORE_PICKUP -> new ShippingResult(BigDecimal.ZERO, 1);
 93	            case COURIER -> {
 94	                if (totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
 95	                    throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
 96	                }
 97	                yield new ShippingResult(new BigDecimal("18.00"), 0);
 98	            }
 99	            case ECONOMY, EXPRESS -> {
100	                try {
101	                    ShippingResult result = transLogClient.quote(
102	                        request.getZipCode(),
103	                        totalWeight,
104	                        request.getShippingMethod(),
105	                        request.getRegion()
106	                    );
107	                    if (result == null) {
108	                        throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
109	                    }
110	                    yield result;
111	                } catch (RuntimeException e) {
112	                    if (e.getMessage().equals("CARRIER_UNAVAILABLE")) {
113	                        throw new ApiException("CARRIER_UNAVAILABLE", 503);
114	                    }
115	                    throw e;
116	                }
117	            }
118	        };
119	    }
120	
121	    private BigDecimal calculateTotalWeight(List<OrderItem> items, Map<String, Product> productMap) {
122	        BigDecimal total = BigDecimal.ZERO;
123	        for (OrderItem item : items) {
124	            Product product = productMap.get(item.getSku());
125	            total = total.add(product.getWeightKg().multiply(new BigDecimal(item.getQuantity())));
126	        }
127	        return total;
128	    }
129	}
